/**
 * This file exists because we have a few things in the build.ts file where we need to test the real vite build behavior.
 * Vitest makes it painful to try and include that in the same file (mocks are hoisted to the top of the file), so here we are.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { build as viteBuild } from 'vite';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { buildSingleExtension } from '../build.js';
import { ROLLUP_OPTIONS } from '../constants.js';
const SENTINEL = 'uie-not-a-real-secret-8f3c1d';
const FAKE_PROCESS_SECRET_VAR = 'UIE_TEST_FAKE_PROCESS_SECRET';
const FAKE_PROCESS_VITE_VAR = 'VITE_UIE_TEST_PROCESS_LEAK';
/**
 * This test suite verifies the real Vite build behavior for single extension builds,
 * ensuring that the build process correctly emits bundles and respects the intended configuration pins.
 * This change originally came from a security vulnerability report. As a result, we must maintain
 * thorough testing to ensure that the build process remains secure and behaves as expected.
 */
describe('buildSingleExtension – config discovery pins', () => {
    let root;
    let outputDir;
    let entryFile;
    let bundleFile;
    beforeEach(() => {
        root = fs.mkdtempSync(path.join(os.tmpdir(), 'uie-cfg-discovery-'));
        outputDir = path.join(root, 'dist');
        fs.mkdirSync(outputDir, { recursive: true });
        writePackageJson();
        entryFile = path.join(root, 'index.js');
        fs.writeFileSync(entryFile, 'export const x = 1;\n');
        bundleFile = path.join(outputDir, 'index.js');
        vi.spyOn(console, 'warn').mockImplementation(() => { });
    });
    afterEach(() => {
        fs.rmSync(root, { recursive: true, force: true });
        delete process.env[FAKE_PROCESS_SECRET_VAR];
        delete process.env[FAKE_PROCESS_VITE_VAR];
        vi.restoreAllMocks();
    });
    function writePackageJson(extra = {}) {
        fs.writeFileSync(path.join(root, 'package.json'), JSON.stringify({ name: 'uie-test-fixture', version: '0.0.0', ...extra }));
    }
    function expectBundleEmitted() {
        expect(fs.existsSync(bundleFile), `build must still emit its bundle at ${bundleFile}`).toBe(true);
        const contents = fs.readFileSync(bundleFile, 'utf8');
        expect(contents.length, 'emitted bundle must not be empty').toBeGreaterThan(0);
        return contents;
    }
    function buildFixture() {
        return buildSingleExtension({
            file: entryFile,
            outputDir,
            emptyOutDir: false,
            root,
            logLevel: 'silent',
        });
    }
    /**
     * DELIBERATE CONTROL HELPER - DO NOT ADD THE SECURITY PINS HERE.
     *
     * Calls vite directly with a config equivalent to the one
     * `buildSingleExtension` uses, minus the pin under test. Its only job is to
     * prove that the fixture genuinely triggers the discovery the pinned tests
     * claim to prevent. If a control ever starts failing, the fixture stopped
     * exercising discovery — fix the fixture, not the control.
     */
    function buildFixtureUnpinned(unpinnedConfig) {
        return viteBuild({
            logLevel: 'silent',
            root,
            ...unpinnedConfig,
            build: {
                lib: {
                    entry: entryFile,
                    name: 'index',
                    formats: ['iife'],
                    fileName: () => 'index.js',
                },
                rollupOptions: ROLLUP_OPTIONS,
                outDir: outputDir,
                emptyOutDir: false,
                minify: false,
            },
        });
    }
    describe('css blocking', () => {
        it('throws with all blocked import paths when an extension imports multiple CSS files', async () => {
            fs.writeFileSync(path.join(root, 'a.css'), '');
            fs.writeFileSync(path.join(root, 'b.scss'), '');
            fs.writeFileSync(entryFile, `import './a.css';\nimport './b.scss';\nexport const x = 1;\n`);
            await expect(buildFixture()).rejects.toThrow(/a\.css.*b\.scss|b\.scss.*a\.css/s);
        });
    });
    describe('vite config', () => {
        function writeMarkerViteConfig(markerFile) {
            fs.writeFileSync(path.join(root, 'vite.config.js'), `import { writeFileSync } from 'fs';\n` +
                `writeFileSync(${JSON.stringify(markerFile)}, 'loaded');\n` +
                `export default {};\n`);
        }
        it('does not evaluate vite.config.js present in the build root', async () => {
            const markerFile = path.join(root, 'vite-config-was-loaded.txt');
            writeMarkerViteConfig(markerFile);
            await buildFixture();
            expectBundleEmitted();
            expect(fs.existsSync(markerFile), 'vite.config.js in customer root must NOT be evaluated').toBe(false);
        });
        // DELIBERATE CONTROL - see buildFixtureUnpinned. Do not add configFile: false.
        it('CONTROL: the same fixture IS discovered without configFile: false', async () => {
            const markerFile = path.join(root, 'vite-config-was-loaded.txt');
            writeMarkerViteConfig(markerFile);
            await buildFixtureUnpinned({});
            expect(fs.existsSync(markerFile), 'control fixture must trigger vite config discovery, otherwise the sibling test proves nothing').toBe(true);
        });
    });
    describe('env files', () => {
        function writeEnvFixture(envFileName) {
            process.env[FAKE_PROCESS_SECRET_VAR] = SENTINEL;
            fs.writeFileSync(path.join(root, envFileName), `VITE_UIE_TEST_LEAK=\${${FAKE_PROCESS_SECRET_VAR}}\n`);
            fs.writeFileSync(entryFile, `export const leaked = import.meta.env.VITE_UIE_TEST_LEAK;\n`);
        }
        it.each(['.env', '.env.local', '.env.production', '.env.production.local'])('does not inline a VITE_ value from %s into the bundle', async (envFileName) => {
            writeEnvFixture(envFileName);
            await buildFixture();
            const bundle = expectBundleEmitted();
            expect(bundle, `${envFileName} in customer root must NOT be loaded`).not.toContain(SENTINEL);
        });
    });
    describe('process environment', () => {
        function writeProcessEnvFixture() {
            process.env[FAKE_PROCESS_VITE_VAR] = SENTINEL;
            fs.writeFileSync(entryFile, `export const leaked = import.meta.env.${FAKE_PROCESS_VITE_VAR};\n`);
        }
        it('does not inline a VITE_ variable from the build process environment', async () => {
            writeProcessEnvFixture();
            await buildFixture();
            const bundle = expectBundleEmitted();
            expect(bundle, 'a VITE_-prefixed variable in the build process environment must NOT reach the build artifact').not.toContain(SENTINEL);
        });
        it('still defines the import.meta.env members that do not depend on envPrefix', async () => {
            fs.writeFileSync(entryFile, `export const mode = import.meta.env.MODE;\n` +
                `export const dev = import.meta.env.DEV;\n` +
                `export const prod = import.meta.env.PROD;\n` +
                `export const ssr = import.meta.env.SSR;\n` +
                `export const base = import.meta.env.BASE_URL;\n`);
            await buildFixture();
            const bundle = expectBundleEmitted();
            expect(bundle).toContain('"production"');
            expect(bundle).toContain('"/"');
            expect(bundle).not.toContain('import.meta.env');
        });
    });
    describe('legitimate builds', () => {
        it('builds a standard TypeScript extension and emits the bundle', async () => {
            fs.writeFileSync(path.join(root, 'utils.ts'), `export const greet = (name: string) => \`hello \${name}\`;\n`);
            fs.writeFileSync(entryFile, `import { greet } from './utils.ts';\nexport const message = greet('world');\n`);
            await buildFixture();
            expectBundleEmitted();
        });
    });
});
